#include "razionale.h"
#include <inttypes.h>
#include <stdio.h>

int64_t mcd_pos(int64_t a, int64_t b) {
    if (a < 0) { a = -a; }
    if (b < 0) { b = -b; }
    while (b != 0) {
        int64_t r = a % b;
        a = b;
        b = r;
    }
    return (a == 0) ? 1 : a;
}

razionale_t raz_crea(int64_t num, int64_t den, bool *ok) {
    if (den == 0) {
        if (ok != nullptr) { *ok = false; }
        return (razionale_t){.num = 0, .den = 1};
    }
    if (den < 0) {
        num = -num;
        den = -den;
    }
    if (num == 0) {
        den = 1;
    } else {
        int64_t g = mcd_pos(num, den);
        num /= g;
        den /= g;
    }
    if (ok != nullptr) { *ok = true; }
    return (razionale_t){.num = num, .den = den};
}

razionale_t raz_somma(razionale_t a, razionale_t b) {
    bool ok = false;
    return raz_crea(a.num * b.den + b.num * a.den, a.den * b.den, &ok);
}

razionale_t raz_moltiplica(razionale_t a, razionale_t b) {
    bool ok = false;
    return raz_crea(a.num * b.num, a.den * b.den, &ok);
}

int raz_confronta(razionale_t a, razionale_t b) {
    int64_t lhs = a.num * b.den;
    int64_t rhs = b.num * a.den;
    return (lhs > rhs) - (lhs < rhs);
}

void raz_stampa(razionale_t r) {
    if (r.den == 1) {
        printf("%" PRId64 "\n", r.num);
    } else {
        printf("%" PRId64 "/%" PRId64 "\n", r.num, r.den);
    }
}

