            razionale_t r = raz_crea((int64_t)n1, (int64_t)d1, &ok);
            if (!ok) { printf("ERRORE DENOMINATORE ZERO\n"); }
            else { raz_stampa(r); }
        } else if ((strcmp(cmd, "ADD") == 0 || strcmp(cmd, "MUL") == 0 || strcmp(cmd, "CMP") == 0) &&
                   sscanf(riga, "%*15s %lld %lld %lld %lld %c", &n1, &d1, &n2, &d2, &extra) == 4) {
