#include "statistica.h"

bool calcola_riepilogo(const misura_t *arr, size_t n, riepilogo_t *out) {
    if (out == nullptr || n == 0 || arr == nullptr) {
        return false;
    }
    double mn = arr[0].valore;
    double mx = arr[0].valore;
    double somma = 0.0;
    for (size_t i = 0; i < n; ++i) {
        double v = arr[i].valore;
        if (v < mn) { mn = v; }
        if (v > mx) { mx = v; }
        somma += v;
    }
    *out = (riepilogo_t){.n = n, .min = mn, .max = mx, .media = somma / (double)n};
    return true;
}

#define TOLLERANZA_ANOMALIA 1e-9
size_t conta_anomalie(const misura_t *arr, size_t n, double soglia) {
    if (arr == nullptr || n == 0) { return 0; }
    size_t cont = 0;
    for (size_t i = 0; i < n; ++i) {
        if (arr[i].valore > soglia + TOLLERANZA_ANOMALIA) {
            ++cont;
        }
    }
    return cont;
}
#undef TOLLERANZA_ANOMALIA

