#include "anello.h"
#include <stdlib.h>

static constexpr size_t MAX_CAP_ANELLO = 64;

struct anello {
    int32_t *dati;
    size_t cap;
    size_t inizio;
    size_t len;
    size_t scartati;
};

anello_t *anello_crea(size_t cap) {
    if (cap < 1 || cap > MAX_CAP_ANELLO) { return nullptr; }
    anello_t *a = malloc(sizeof(*a));
    if (a == nullptr) { return nullptr; }
    a->dati = malloc(cap * sizeof(*a->dati));
    if (a->dati == nullptr) { free(a); return nullptr; }
    a->cap = cap;
    a->inizio = 0;
    a->len = 0;
    a->scartati = 0;
    return a;
}

void anello_distruggi(anello_t *a) {
    if (a == nullptr) { return; }
    free(a->dati);
    free(a);
}

bool anello_inserisci(anello_t *a, int32_t val, bool *sovrascritto) {
    if (a == nullptr) { return false; }
    if (a->len == a->cap) {
        a->dati[a->inizio] = val;
        a->inizio = (a->inizio + 1) % a->cap;
        ++a->scartati;
        if (sovrascritto != nullptr) { *sovrascritto = true; }
    } else {
        a->dati[(a->inizio + a->len) % a->cap] = val;
        ++a->len;
        if (sovrascritto != nullptr) { *sovrascritto = false; }
    }
    return true;
}

bool anello_estrai(anello_t *a, int32_t *out) {
    if (a == nullptr || a->len == 0) { return false; }
    if (out != nullptr) { *out = a->dati[a->inizio]; }
    a->inizio = (a->inizio + 1) % a->cap;
    --a->len;
    return true;
}

bool anello_leggi_i(const anello_t *a, size_t idx, int32_t *out) {
    if (a == nullptr || out == nullptr || idx >= a->len) { return false; }
    *out = a->dati[(a->inizio + idx) % a->cap];
    return true;
}

void anello_svuota(anello_t *a) {
    if (a == nullptr) { return; }
    a->inizio = 0;
    a->len = 0;
}

size_t anello_len(const anello_t *a) { return (a != nullptr) ? a->len : 0; }
size_t anello_cap(const anello_t *a) { return (a != nullptr) ? a->cap : 0; }
size_t anello_scartati(const anello_t *a) { return (a != nullptr) ? a->scartati : 0; }

