#include <inttypes.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "tabella_hash.h"

typedef struct studente { int32_t matricola; char *nome; int32_t voto; size_t *cont_dist; } studente_t;
typedef struct ctx_media { int64_t somma; size_t n; } ctx_media_t;

static uint64_t hash_i32(const void *p) {
    uint64_t x = (uint32_t)(*(const int32_t *)p);
    x ^= x >> 30; x *= 0xbf58476d1ce4e5b9ULL; x ^= x >> 27; x *= 0x94d049bb133111ebULL; return x ^ (x >> 31);
}

static bool uguali_i32(const void *a, const void *b) { return *(const int32_t *)a == *(const int32_t *)b; }

static void distruggi_studente(void *p) {
    studente_t *s = p; if (s == nullptr) { return; }
    if (s->cont_dist != nullptr) { ++(*s->cont_dist); }
    free(s->nome); free(s);
}

static void somma_voti(const void *k, void *v, void *ctx) {
    (void)k; ctx_media_t *cm = ctx; cm->somma += ((const studente_t *)v)->voto; ++cm->n;
}

int main(void) {
    size_t creati = 0, distrutti = 0;
    tabella_hash_t *per_mat = ht_crea(&(ht_config_t){
        .cap_iniziale = 4, .hash = hash_i32, .uguali = uguali_i32,
        .distruggi_chiave = free, .distruggi_valore = distruggi_studente});
    tabella_hash_t *per_nome = ht_crea(&(ht_config_t){
        .cap_iniziale = 4, .hash = ht_hash_stringa, .uguali = ht_uguali_stringa,
        .distruggi_chiave = free});
    if (per_mat == nullptr || per_nome == nullptr) { ht_distruggi(per_nome); ht_distruggi(per_mat); return EXIT_FAILURE; }
    char riga[256], cmd[16], nome[48], extra = '\0';
    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%15s", cmd) != 1) { continue; }
        long long mat = 0, voto = 0;
        if (strcmp(cmd, "ADD") == 0 && sscanf(riga, "ADD %lld %47s %lld %c", &mat, nome, &voto, &extra) == 3) {
            int32_t m32 = (int32_t)mat;
            studente_t *vecchio = ht_cerca(per_mat, &m32);
            if (vecchio != nullptr) { ht_rimuovi(per_nome, vecchio->nome); }
            int32_t *km = malloc(sizeof(*km)); char *kn = strdup(nome); studente_t *s = malloc(sizeof(*s));
            if (km == nullptr || kn == nullptr || s == nullptr) { free(km); free(kn); free(s); ht_distruggi(per_nome); ht_distruggi(per_mat); return EXIT_FAILURE; }
            s->nome = strdup(nome);
            if (s->nome == nullptr) { free(km); free(kn); free(s); ht_distruggi(per_nome); ht_distruggi(per_mat); return EXIT_FAILURE; }
            *km = m32; s->matricola = m32; s->voto = (int32_t)voto; s->cont_dist = &distrutti; ++creati;
            ht_esito_t es = ht_inserisci(per_mat, km, s);
            if (es == HT_ERRORE || ht_inserisci(per_nome, kn, s) == HT_ERRORE) {
                if (es == HT_ERRORE) { free(km); distruggi_studente(s); }
                free(kn); ht_distruggi(per_nome); ht_distruggi(per_mat); return EXIT_FAILURE;
            }
            printf("ADD %" PRId32 ": %s\n", m32, (es == HT_INSERITO) ? "INSERITO" : "AGGIORNATO");
        } else if (strcmp(cmd, "BY_ID") == 0 && sscanf(riga, "BY_ID %lld %c", &mat, &extra) == 1) {
            int32_t m32 = (int32_t)mat; const studente_t *s = ht_cerca(per_mat, &m32);
            if (s != nullptr) { printf("ID %" PRId32 ": %s (%" PRId32 ")\n", m32, s->nome, s->voto); }
            else { printf("ID %" PRId32 ": NON TROVATO\n", m32); }
        } else if (strcmp(cmd, "BY_NAME") == 0 && sscanf(riga, "BY_NAME %47s %c", nome, &extra) == 1) {
            const studente_t *s = ht_cerca(per_nome, nome);
            if (s != nullptr) { printf("NAME %s: #%" PRId32 " (%" PRId32 ")\n", nome, s->matricola, s->voto); }
            else { printf("NAME %s: NON TROVATO\n", nome); }
        } else if (strcmp(cmd, "DEL") == 0 && sscanf(riga, "DEL %lld %c", &mat, &extra) == 1) {
            int32_t m32 = (int32_t)mat; void *estr = nullptr;
            if (!ht_estrai(per_mat, &m32, &estr)) { printf("DEL %" PRId32 ": NON TROVATO\n", m32); }
            else { studente_t *s = estr; ht_rimuovi(per_nome, s->nome); distruggi_studente(s); printf("DEL %" PRId32 ": OK\n", m32); }
        } else if (strcmp(cmd, "MEDIA") == 0 && sscanf(riga, "MEDIA %c", &extra) != 1) {
            ctx_media_t cm = {}; ht_visita(per_mat, somma_voti, &cm);
            double media = (cm.n > 0) ? ((double)cm.somma / (double)cm.n) : 0.0;
            printf("MEDIA (len=%zu, cap=%zu): %.2f\n", ht_len(per_mat), ht_cap(per_mat), media);
        } else { ht_distruggi(per_nome); ht_distruggi(per_mat); return EXIT_FAILURE; }
    }
    ht_distruggi(per_nome); ht_distruggi(per_mat);
    printf("FINE creati=%zu distrutti=%zu\n", creati, distrutti);
    return EXIT_SUCCESS;
}
